     records: mergeById(parts.map((p) => p.records)),
     findings: mergeById(parts.map((p) => p.findings)),
     themes: mergeById(parts.map((p) => p.themes)),
     requirements: mergeById(parts.map((p) => p.requirements)),
   };
 }

